 void refreshGeometry(){android.content.SharedPreferences p=getSharedPreferences("settings",0);int nx=Math.min(width-1,width*p.getInt("x",5)/100),ny=Math.min(height-1,height*p.getInt("y",60)/100),nw=Math.max(1,Math.min(width-nx,width*p.getInt("w",90)/100)),nh=Math.max(1,Math.min(height-ny,height*p.getInt("h",15)/100));if(nx!=x||ny!=y||nw!=cw||nh!=ch){revision++;previous="";label.setVisibility(View.INVISIBLE);}x=nx;y=ny;cw=nw;ch=nh;interval=p.getInt("interval",500);int sy=p.getInt("subtitleY",0);int yy=sy>0?height*sy/100:(y+ch<height-100?y+ch:Math.max(0,y-120));int xx=width*p.getInt("subtitleX",5)/100;int ww=Math.min(width-xx,width*p.getInt("subtitleW",90)/100);if(subtitleParams.y!=yy||subtitleParams.x!=xx||subtitleParams.width!=ww){subtitleParams.y=yy;subtitleParams.x=xx;subtitleParams.width=ww;wm.updateViewLayout(label,subtitleParams);}label.setTextSize(p.getInt("size",20));}
